import { Link } from "react-router-dom";

function ChildCard({ child }) {
  const imageUrl = child.image
    ? child.image.startsWith("http") || child.image.startsWith("data:")
      ? child.image
      : child.image.startsWith("/uploads")
        ? `http://localhost:3000${child.image}`
        : `http://localhost:3000/uploads/${child.image}`
    : "https://via.placeholder.com/300x180?text=No+Image";

  return (
    <Link to={`/child/${child.id}`} style={{ textDecoration: "none", color: "inherit" }}>
      <div className="card">
        <div style={{ height: "200px", overflow: "hidden", borderRadius: "16px 16px 0 0" }}>
          <img
            src={imageUrl}
            alt={child.name}
            style={{ width: "100%", height: "200px", objectFit: "cover", objectPosition: "center center" }}
            onError={(e) => { e.target.src = "https://via.placeholder.com/300x200?text=No+Image"; }}
          />
        </div>
        <div className="card-header" style={{ paddingTop: "16px" }}>
          <div className="card-title">👶 {child.name}</div>
          <span className="badge badge-primary">{child.class}</span>
        </div>
        <div className="card-content">
          <p><strong>Age:</strong> {child.age} years</p>
          <p><strong>Class:</strong> {child.class}</p>
          <p style={{ marginTop: "15px", fontSize: "0.9rem", color: "#667eea" }}>Click to view profile →</p>
        </div>
      </div>
    </Link>
  );
}

export default ChildCard;
